import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Isolate Demo',
      theme: ThemeData(colorSchemeSeed: Colors.indigo, useMaterial3: true),
      home: const JsonParsePage(),
    );
  }
}

class JsonParsePage extends StatefulWidget {
  const JsonParsePage({super.key});

  @override
  State<JsonParsePage> createState() => _JsonParsePageState();
}

class _JsonParsePageState extends State<JsonParsePage> {
  int _userCount = 0;
  bool _loading = false;
  int _elapsedMs = 0;

  /// 必须是顶层函数或 static 方法，才能作为 compute 的入口点
  /// （闭包无法被序列化后发送到子 Isolate）
  static List<String> parseUsers(String rawJson) {
    final List<dynamic> list = jsonDecode(rawJson) as List<dynamic>;
    return list.map((e) => '${e['name']}<${e['email']}>').toList();
  }

  /// 构造一份「重负载」JSON 字符串，模拟真实业务里的大报文
  String _buildPayload() {
    final users = List.generate(
      200000,
      (i) => {'name': 'user_$i', 'email': 'user_$i@example.com'},
    );
    return jsonEncode(users);
  }

  Future<void> _runParse({bool useIsolate = true}) async {
    setState(() => _loading = true);
    final payload = _buildPayload();
    final sw = Stopwatch()..start();

    List<String> result;
    if (useIsolate) {
      // 耗时计算放到子 Isolate，主线程继续渲染动画
      result = await compute(parseUsers, payload);
    } else {
      // 对照组：直接在主 Isolate 解析，会明显掉帧
      result = parseUsers(payload);
    }

    sw.stop();
    if (!mounted) return;
    setState(() {
      _userCount = result.length;
      _elapsedMs = sw.elapsedMilliseconds;
      _loading = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('compute 异步解析 JSON')),
      body: Center(
        child: _loading
            ? const CircularProgressIndicator()
            : Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Text('已解析用户数: $_userCount',
                      style: Theme.of(context).textTheme.headlineSmall),
                  Text('耗时: $_elapsedMs ms'),
                  const SizedBox(height: 24),
                  FilledButton(
                    onPressed: () => _runParse(useIsolate: true),
                    child: const Text('用 compute 解析（流畅）'),
                  ),
                  const SizedBox(height: 8),
                  OutlinedButton(
                    onPressed: () => _runParse(useIsolate: false),
                    child: const Text('在主 Isolate 解析（卡顿）'),
                  ),
                  const SizedBox(height: 24),
                  // 解析过程中留意下方动画是否还在转动
                  const CircularProgressIndicator.adaptive(),
                  const Text('解析时观察圆圈是否仍在转动'),
                ],
              ),
      ),
    );
  }
}

